<div class="page-header"><div><h1>Mail</h1><p class="sub">Zoek en lees berichten uit je eigen mailboxen.</p></div><a class="btn btn-primary" href="<?=e(url('mail/compose'))?>"><?=icon('edit')?>Mail schrijven</a></div>
<?php if(!$accounts):?><div class="card empty-state"><div class="empty-state-icon"><?=icon('mail')?></div><h2>Nog geen actieve mailbox</h2><p><a href="<?=e(url('mail/accounts'))?>">Voeg een mailaccount toe</a> om je berichten te lezen.</p></div><?php else:?>
<form method="get" action="<?=e(url('mail'))?>" class="card search-form" data-loading>
<div class="form-grid">
<div class="field"><label for="account">Account</label><select id="account" name="account"><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=(int)$a['id']===$accountId?'selected':''?>><?=e($a['label'])?></option><?php endforeach;?></select></div>
<div class="field"><label for="folder">Map</label><select id="folder" name="folder"><?php foreach($folders?:[['name'=>'INBOX']] as $f):?><option value="<?=e($f['name'])?>" <?=$f['name']===$folder?'selected':''?>><?=e($f['name'])?></option><?php endforeach;?></select></div>
<div class="field"><label for="q">Zoeken</label><input id="q" name="q" value="<?=e($term)?>" type="search" placeholder="Naam, onderwerp of tekst"></div>
</div><div class="actions"><label class="checkbox-row"><input type="checkbox" name="unread" value="1" <?=!empty($_GET['unread'])?'checked':''?>>Alleen ongelezen</label><button class="btn btn-secondary" type="submit">Zoeken</button></div>
</form>
<?php if($error):?><div class="alert alert-error" role="alert"><?=icon('alert')?><?=e($error)?></div><?php elseif(!$mailbox['messages']):?><div class="card empty-state"><div class="empty-state-icon"><?=icon('box')?></div><h2>Geen berichten gevonden</h2><p>Probeer een andere map of zoekterm.</p></div><?php else:?>
<div class="card message-list"><?php foreach($mailbox['messages'] as $m):?><a class="message-row" href="<?=e(url('mail/message?'.http_build_query(['account'=>$accountId,'folder'=>$folder,'uid'=>$m['uid'],'validity'=>$m['uidvalidity']])))?>"><div><div class="message-subject"><?=e($m['subject']?:'Zonder onderwerp')?></div><div class="sub"><?=e($m['from'])?></div><div class="hint"><?=e($m['date'])?></div></div><span class="badge <?=$m['seen']?'':'badge-accent'?>"><?=$m['seen']?'Gelezen':'Nieuw'?></span></a><?php endforeach;?></div>
<div class="actions pagination"><span class="sub"><?=(int)$mailbox['total']?> berichten</span><?php if($offset>0):?><a class="btn btn-secondary btn-sm" href="<?=e(url('mail?'.http_build_query(array_merge($_GET,['offset'=>max(0,$offset-25)]))))?>">Vorige</a><?php endif;?><?php if($offset+25<$mailbox['total']):?><a class="btn btn-secondary btn-sm" href="<?=e(url('mail?'.http_build_query(array_merge($_GET,['offset'=>$offset+25]))))?>">Volgende</a><?php endif;?></div>
<?php endif;endif;?>
